const item = $input.first().json;

// Extract raw text from Ollama response
const raw = item?.message?.content || item?.choices?.[0]?.message?.content || '';

if (!raw) {
  console.log('[Evaluate] Empty Ollama response for job, skipping');
  return [];
}

let parsed;
try {
  // Strip potential markdown code fences
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  console.log(`[Evaluate] Failed to parse JSON: ${raw.substring(0, 200)}`);
  return [];
}

if (typeof parsed.match !== 'boolean') {
  console.log(`[Evaluate] Invalid response shape: ${JSON.stringify(parsed)}`);
  return [];
}

console.log(`[Evaluate] ${parsed.match ? '✅ MATCH' : '❌ skip'} — ${parsed.reason}`);

return [{ json: { match: parsed.match, reason: parsed.reason, url: parsed.url } }];
